1	// THE TERMINAL TRANSITION, IN CODE (#892; tasks-dispatch DESIGN §6.5, §15.18).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (§15.19, reversed by §15.31 /
6	// #1373). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
13	// JUDGMENT — which outcome, and the prose of what happened — and the CODE
14	// performs the transition. A session that stops early now leaves an item that is
15	// visibly unconverged, rather than one that looks finished and is not.
16	//
17	// Usage:
18	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
19	//                          --summary <text> [--pr <n>]
20	
21	import { pathToFileURL } from 'node:url';
22	import { renderTaskExec } from '../run-record.mjs';
23	import {
24	  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, isWorkItemTitle, machineBlockOf,
25	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
26	  QUEUED_LABEL, IN_REVIEW_LABEL,
27	  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
28	  editItemBody, withEndsWhen,
29	} from './work-item.mjs';
30	
31	// What a session may claim, and what each one means for the item. `record` is the
32	// execution-record status, and `null` means no record: an approval park is a run
33	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
34	// a fifth status would be stored data every decoder in the fleet must learn.
35	export const OUTCOMES = Object.freeze({
36	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
37	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
38	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
39	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
40	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
41	});
42	
43	export function parseArgs(argv) {
44	  const args = {};
45	  for (let n = 0; n < argv.length; n += 1) {
46	    const m = /^--([a-z-]+)$/.exec(argv[n]);
47	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
48	  }
49	  const issue = Number(args.issue);
50	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
51	  if (!OUTCOMES[args.outcome]) {
52	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
53	  }
54	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
55	  if (args.outcome === 'approval' && !args.pr) {
56	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
57	  }
58	  return { issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null };
59	}
60	
61	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
62	// terminal state onto the wrong issue: this runs from a session, whose whole
63	// notion of which item it holds came from an untrusted fire payload.
64	export function refusal(item, issue) {
65	  if (!item) return `#${issue} could not be read`;
66	  // A marked issue IS its own item (DESIGN §16.1), so the title test cannot be the
67	  // membership test any more: what says this is one is the machine block adoption
68	  // wrote — never the body's first line, which on a marked issue is a person's prose.
69	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null) {
70	    return `#${issue} is not a Claudinite work item`;
71	  }
72	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
73	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
74	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
75	  }
76	  return null;
77	}
78	
79	// The record line for this item, or null where the vocabulary has no true answer.
80	export const recordLine = (item, status) => {
81	  const parsed = parseWorkItemTitle(item.title);
82	  return status && parsed
83	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
84	    : null;
85	};
86	
87	// The comment one converge writes: the session's account, then the record, so a
88	// reader and a parser both find what they came for in one place.
89	export function convergeComment(item, { summary, pr, record }) {
90	  const rec = recordLine(item, record);
91	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
92	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
93	  return `${summary.trim()}${waiting}${line}`;
94	}
95	
96	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
97	// `await api.…` calls, which silently made REST the only way to perform them —
98	// and the sessions `invoke.mjs` hands work to have no REST route to their own
99	// repository, so the last step of every agentic run was the one step that
100	// environment could not take.
101	//
102	// So the sequence is planned as OPS and executed by whoever can. The planner is
103	// the single source of what a convergence IS; the executors differ only in
104	// transport. The session still supplies nothing but the judgment.
105	//
106	// Removes are granular and unconditional — every spelling of the status being
107	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
108	// items outlive its converges, so an item may wear an older engine's spelling).
109	export function convergeOps(item, plan) {
110	  const spec = OUTCOMES[plan.outcome];
111	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];
112	
113	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
114	  // the durable one (Actions logs expire, the item does not), while this printed
115	  // copy lands in the session transcript, which is what the usage fold reads for
116	  // the task-status census.
117	  const rec = recordLine(item, spec.record);
118	  if (rec) ops.push({ kind: 'record', line: rec });
119	
120	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
121	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
122	  }
123	  // ONE label, on both paths: the outcome IS the status. A park in particular is
124	  // never a pair, so nothing can be half-applied (#1385).
125	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
126	
127	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
128	  // merge or close the pull request; this says the same thing where the janitor can
129	  // read it, so the item ends when that happens instead of waiting for someone to
130	  // notice it already did. Every park that names one gets it, not only `approval`.
131	  if (!spec.closes && plan.pr) {
132	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
133	  }
134	
135	  if (spec.closes) {
136	    // A MARKED ISSUE IS NOT THE SESSION'S TO CLOSE (§16.1, §16.5): the terminal
137	    // status stands on the open issue, and whether the issue itself is finished
138	    // belongs to the person who opened it.
139	    if (isWorkItemTitle(item.title ?? '')) ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
140	    return ops;
141	  }
142	
143	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
144	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
145	  // leaves `claude-queued` standing, because re-arming work that writes code is a
146	  // person's decision and that standing label is what stops the next scheduler run
147	  // queueing a second run of the same request. Only a LEGACY shadow item writes
148	  // back to a different issue.
149	  const { request } = parseWorkItemBody(item.body ?? '');
150	  if (request && request !== item.number && plan.outcome === 'approval') {
151	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
152	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
153	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
154	  }
155	  return ops;
156	}
157	
158	// THE REST EXECUTOR — what an Actions run does, unchanged in behaviour.
159	export async function convergeItem(api, gh, repo, plan, { log = console.log } = {}) {
160	  const item = await api.readIssue(gh, repo, plan.issue);
161	  const no = refusal(item, plan.issue);
162	  if (no) return { ok: false, error: no };
163	
164	  let closed = false;
165	  for (const op of convergeOps(item, plan)) {
166	    if (op.kind === 'comment') await api.comment(gh, repo, op.issue, op.body);
167	    else if (op.kind === 'record') log(op.line);
168	    else if (op.kind === 'removeLabel') await api.removeLabel(gh, repo, op.issue, op.name);
169	    else if (op.kind === 'addLabel') await api.addLabel(gh, repo, op.issue, op.name);
170	    else if (op.kind === 'setBody') await api.setIssueBody(gh, repo, op.issue, op.body);
171	    else if (op.kind === 'close') { await api.closeIssue(gh, repo, op.issue, op.stateReason); closed = true; }
172	  }
173	  const { request } = parseWorkItemBody(item.body ?? '');
174	  return { ok: true, closed, request: request ?? null };
175	}
176	
177	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
178	// does have. Two differences forced by that surface, both handled here rather than
179	// left to the session to work out:
180	//
181	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
182	//    granular removes and adds are folded into the FINAL set here, computed from the
183	//    labels this item was read with. Everything not a status label is carried through.
184	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
185	//    usage fold reads the census out of the session transcript.
186	export function sessionScript(item, plan, repo) {
187	  const [owner, name] = String(repo).split('/');
188	  const lines = [];
189	  let n = 0;
190	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
191	
192	  // The item's own label set can be computed exactly, because the item was read
193	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
194	  // read-modify-write naming only the change, and never as a computed set, which
195	  // would silently drop every label this process never saw.
196	  const own = new Set(labelNames(item));
197	  const foreign = [];
198	  // The body write folds into the item's own `issue_write`, which is one call
199	  // either way. A park never closes, so the step it folds into is the trailing
200	  // label write below.
201	  let newBody = null;
202	
203	  for (const op of convergeOps(item, plan)) {
204	    if (op.kind === 'comment') {
205	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
206	    } else if (op.kind === 'record') {
207	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
208	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
209	      if (op.issue === item.number) {
210	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
211	      } else {
212	        foreign.push(op);
213	      }
214	    } else if (op.kind === 'setBody' && op.issue === item.number) {
215	      newBody = op.body;
216	    } else if (op.kind === 'close') {
217	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
218	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
219	      own.clear();
220	    }
221	  }
222	  // A park never closed, so its label write is still owed.
223	  if (own.size) {
224	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
225	      + ` labels \`${JSON.stringify([...own])}\``
226	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
227	  }
228	  for (const op of foreign) {
229	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
230	      + ` Read that issue's current labels first and write them back with only this one change —`
231	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
232	  }
233	  return lines.join('\n');
234	}
235	
236	// CAN THIS PROCESS ACTUALLY REACH THE REPO? Read the status, never the body: a
237	// token that is absent, expired, or simply not a REST credential all answer with a
238	// plausible JSON object and a 401/403, and a body-only test reads that as a repo.
239	// One request, before any write, because the alternative is discovering it halfway
240	// through a sequence that was meant to be atomic.
241	export async function canReachRepo(gh, repo) {
242	  const { status } = await gh(`/repos/${repo}`);
243	  return status === 200;
244	}
245	
246	async function main() {
247	  const plan = parseArgs(process.argv.slice(2));
248	  if (plan.error) {
249	    console.error(`converge-item: ${plan.error}`);
250	    process.exit(2);
251	  }
252	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
253	  const api = await import('../github.mjs');
254	  const { repo } = actionRepoContext();
255	  const gh = repo ? makeGh() : null;
256	
257	  if (repo && await canReachRepo(gh, repo)) {
258	    const res = await convergeItem(api, gh, repo, plan);
259	    if (!res.ok) { console.error(`converge-item: ${res.error}`); process.exit(1); }
260	    console.log(res.closed
261	      ? `converged #${plan.issue}: closed ${OUTCOMES[plan.outcome].label}`
262	      : `converged #${plan.issue}: parked ${OUTCOMES[plan.outcome].label}, left open for a person`);
263	    return;
264	  }
265	
266	  // NO REST ROUTE — the normal case for a session, not a breakage. The session has
267	  // GitHub access of its own; what it lacks is a way to reach it from a
268	  // subprocess. So the same plan is emitted addressed to the tools it does have,
269	  // and the session performs its own convergence. Nothing is deferred and nobody
270	  // else is involved: one run finishes one item.
271	  const sessionRepo = repo ?? process.env.CLAUDINITE_ITEM_REPO ?? null;
272	  if (!sessionRepo) {
273	    console.error('converge-item: no repository — pass GITHUB_REPOSITORY or CLAUDINITE_ITEM_REPO');
274	    process.exit(2);
275	  }
276	  const item = JSON.parse(process.env.CLAUDINITE_ITEM_JSON ?? 'null');
277	  if (!item) {
278	    console.error('converge-item: this process cannot reach the REST API, so it cannot read the item either.\n'
279	      + 'Re-run with CLAUDINITE_ITEM_JSON set to the issue as your GitHub tools returned it'
280	      + ' (number, title, body, state, labels), and it will print the exact calls to make.');
281	    process.exit(2);
282	  }
283	  const no = refusal(item, plan.issue);
284	  if (no) { console.error(`converge-item: ${no}`); process.exit(1); }
285	
286	  console.log(`converge-item: no REST route from this session, so the transition is yours to execute.\n`
287	    + `Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n`);
288	  console.log(sessionScript(item, plan, sessionRepo));
289	}
290	
291	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
292	  main().catch((e) => { console.error(e); process.exit(1); });
293	}
294

